    termsS1H: "1. स्वीकृति",
    termsS1:
      "खाता बनाकर या साहिति का उपयोग करके आप इन शर्तों से सहमत होते हैं। यदि सहमत नहीं हैं तो प्रोटोटाइप का उपयोग न करें।",
    termsS2H: "2. पात्रता",
    termsS2:
      "साहिति भारत के उन निवासियों के लिए उपलब्ध है जिनकी आयु 18 वर्ष या अधिक है और जो भारतीय ठेका अधिनियम 1872 के अंतर्गत ठेका करने योग्य हैं।",
    termsS3H: "3. प्रोटोटाइप स्थिति",
    termsS3:
      "साहिति स्मार्ट इंडिया हैकेथन 2026 के लिए बनाया गया प्रदर्शन-प्रोटोटाइप है। सुविधाएँ, डेटा और उपलब्धता बिना सूचना बदल या हट सकती हैं। गणनाएँ, योजना-सारांश, बाज़ार के आँकड़े और नक्शे के जोखिम स्कोर केवल उदाहरण हैं। ब्याज दरें, अवधियाँ, पात्रता नियम और दस्तावेज़ आवश्यकताएँ किसी कदम से पहले बैंक या संबंधित सरकारी पोर्टल से पुष्टि करें।",
    termsS4H: "4. कोई व्यावसायिक सलाह नहीं",
    termsS4:
      "सहायक के जवाबों समेत साहिति में कुछ भी वित्तीय, क़ानूनी, कर या निवेश सलाह नहीं है, और किसी परिणाम की गारंटी नहीं है। वित्तीय प्रतिबद्धता से पहले योग्य व्यावसायिक, अपने बैंक या संबंधित विभाग से परामर्श करें।",
    termsS5H: "5. आपका खाता",
    termsS5:
      "अपना पासवर्ड गोपनीय रखना और आपके खाते से हुई गतिविधि की ज़िम्मेदारी आपकी है। 30 मिनट निष्क्रियता के बाद सत्र स्वतः साइन-आउट हो जाता है।",
    termsS6H: "6. स्वीकार्य उपयोग",
    termsS6P1:
      "केवल व्यवसाय से जुड़ी सामग्री पोस्ट करें। व्यक्तिगत, राजनीतिक और अवैध सामग्री की अनुमति नहीं है।",
    termsS6P2: "किसी अन्य व्यक्ति की निजी जानकारी या वित्तीय क्रेडेंशियल पोस्ट न करें।",
    termsS6P3: "सरकारी योजनाओं या गारंटीड रिटर्न के बारे में झूठे दावे न करें।",
    termsS6P4: "दूसरे खातों तक पहुँचने या सेवा में बाधा डालने की कोशिश न करें।",
    termsS6Outro:
      "आपकी पोस्ट की सामग्री का स्वामित्व आपके पास रहता है और आप साहिति को प्रोटोटाइप के अन्य साइन-इन उपयोगकर्ताओं को दिखाने की अनुमति देते हैं। इन नियमों को तोड़ने वाली सामग्री हटाई जा सकती है।",
    termsS7H: "7. देयता की सीमा",
    termsS7:
      "प्रोटोटाइप जैसा है वैसा ही दिया जाता है, बिना किसी वारंटी के। क़ानून द्वारा अनुमत सीमा तक, साहिति के उपयोग से उठने किसी भी व्यावसायिक हानि, लाभ हानि या अप्रत्यक्ष हानि के लिए परियोजना टीम उत्तरदायी नहीं है।",
    termsS8H: "8. लागू क़ानून और विवाद",
    termsS8:
      "इन शर्तों पर भारत के क़ानून लागू होते हैं। किसी भी विवाद को पंचाट और सुलह अधिनियम 1996 के अंतर्गत एकल पंच के समक्ष संदर्भित किया जाएगा। पंचाट का स्थान नई दिल्ली और भाषा अंग्रेज़ी होगी। अन्य सभी मामलों में नई दिल्ली की अदालतों को अनन्य क्षेत्राधिकार प्राप्त होगा।",

