      "તમારી માર્જિન રકમને પ્રોજેક્ટ ખર્ચ, લોન રકમ અને સમજી શકાય તેવી ચૂકવણી કોષ્ટકમાં બદલો.",
    landingStep1Alt: "મહારાષ્ટ્રની પડોશની કિરાણા દુકાનની સ્નેક્સ થાળીઓ",
    landingStep2Body: "બેંક શાખાની લાઇનમાં ઊભા રહેતા પહેલા બેંક કયા કાગળો માંગશે તે જાણી લો.",
    landingStep2Alt: "ડેસ્ક પર કાગળિયામજૂરી ભરતા હાથ",
    landingStep3Body:
      "નકશા પર લોહેગાંવની ખરી દુકાનો, અને સાહિતિ સેફ ઝોન જે બતાવે છે ધંધો ક્યાં ચાલે છે.",
    landingStep3Alt: "દિલ્હીના બજારના ઠેલા પર સજાવેલી તાજી શાકભાજી અને ફળો",
    landingEverydayKicker: "રોજના ઉદ્યમી માટે બનાવેલું",
    landingEverydayBody:
      "લોનના આંકડા, દસ્તાવેજો અને લોહેગાંવનો નકશો અસલ જીવન પાસે રાખો — પુસ્તિકામાં દટાવી નહીં.",
    landingOpenSahiti: "સાહિતિ ખોલો",
    landingDisclaimer:
      "સ્માર્ટ ઇન્ડિયા હેકાથોન 2026, MoSJE સમસ્યા વિધાન 26091 માટે પ્રોટોટાઇપ. એપમાં બતાવેલા બજાર અને નકશાના આંકડા નમૂના સંશોધન છે, સત્તાવાર ડેટા નહીં.",
    marketDhanoriDemand: "બે પૈડાં વાહનોનું વધતું આવાગમન સમારકામ-જાળવણીની માંગ વધારે છે.",
    marketDhanoriRoi: "સંતુલિત સાધનોની રોકાણ અને પુનઃ આવતા સ્થાનિક ગ્રાહકો ઝડપી બ્રેક-ઇવન આપી શકે.",
    marketAdypuDemand: "સસ્તું ભોજન અને સાંજના સ્નેક્સની સતત વિદ્યાર્થી માંગ, સેમેસ્ટર મુજબ બદલાય.",
    marketAdypuRoi:
      "નાના કદની દુકાનો સ્થિર વેચાણ મેળવી શકે, ભાડું અને ખોરાક બગાડ નિયંત્રિત હોય તો.",
    marketAirportDemand: "રોજિંદી ઘરેલુ માંગ દૂધ અને વધારાના ડેરી ઉત્પાદનોને બળ આપે.",
    marketAirportRoi: "ઠંડી-સાંકળ નિયંત્રણ અને બગાડ નિવારણ માર્જિનનું કેન્દ્ર છે.",
    marketCharholiDemand: "વાવણી ચક્ર અને વરસાદની અપેક્ષા મુજબ ઇનપુટની માંગ બદલાય.",
    marketCharholiRoi: "મોસમી ચરમસીમામાં કાર્યકારી મૂડ આયોજન ખાલી માલ ઘટાડે.",
    marketPorwalDemand:
      "વિદ્યાર્થીઓ અને નોકરી કરતા રહેવાસીઓ વ્યસ્તતા ટકાવે; સંસ્થાકીય માંગ કેન્દ્રિત છે.",
    marketPorwalRoi: "મિલકત ખર્ચ ઊંચો, પણ સ્થિર વ્યસ્તતા અનુમાનિત રોકડ પ્રવાહ આપી શકે.",
    marketSantNagarDemand: "ઘની નિવાસી માંગ સ્થિર, પણ સુવિધા છૂટક વેચાણની સ્પર્ધા દેખાય.",
    marketSantNagarRoi: "માર્જિન ખરીદી શિસ્ત અને માલ ફરવાની ગતિ પર આધારે.",
    marketWagholiDemand: "લગ્ન અને તહેવારોની મોસમી માંગ શિખરો બનાવે; રોજિંદી માંગ મધ્યમ.",
    marketWagholiRoi: "માલની પસંદગી જ મુખ્ય ROI ચાલક; ધીમા ડિઝાઇનનો વધુ સ્ટોક ટાળો.",
    marketLohegaonDemand:
      "માંગ પ્રસંગ-આધારિત અને ભાવ પ્રત્યે સંવેદનશીલ. વિશ્વાસ અને હોલમાર્કિંગ પુનઃખરીદ પર અસર કરે.",
    marketLohegaonRoi: "વધુ સેટઅપ ખર્ચ અને ધીમો માલ ફેરફાર એટલે લાંબો પરતાવાર સમય.",
    aiPageDescription: "લોન, યોજના, દસ્તાવેજો કે બજાર વિશે પૂછો — તમારી ભાષામાં.",
    "cat.Hardware": "હાર્ડવેર",
