    termsS3H: "3. પ્રોટોટાઇપની સ્થિતિ",
    termsS3:
      "સાહિતિ એ સ્માર્ટ ઇન્ડિયા હેકાથોન 2026 માટે બનાવેલ ડેમો પ્રોટોટાઇપ છે. સુવિધાઓ, ડેટા અને ઉપલબ્ધતા કોઈ પણ સમયે બદલાઈ અથવા દૂર થઈ શકે છે. ગણતરી, યોજનાની સારાંશ, બજાર આંકડા અને નકશાના જોખમ સ્કોર ફક્ત ઉદાહરણ માટે છે. વ્યાજ દર, સમયમર્યાદા, પાત્રતાના નિયમો અને દસ્તાવેજ જરૂરિયાતો કાર્યવાહી કરતા પહેલાં બેંક અથવા સંબંધિત સરકારી પોર્ટલ પર ખાતરી કરો.",
    termsS4H: "4. વ્યાવસાયિક સલાહ નથી",
    termsS4:
      "સાહિતિમાં કર્યું કોઈપણ કંઈ, સહાયકના જવાબ સહિત, નાણાકીય, કાનૂની, કર અથવા રોકણાત્મક સલાહ નથી અને કોઈ પરિણામની ખાતરી નથી. નાણાકીય નિર્ણય લેવા પહેલાં લાયક વ્યાવસાયિક, તમારી બેંક અથવા સંબંધિત વિભાગની સલાહ લો.",
