    termsS6P2: "অন্য কারও ব্যক্তিগত তথ্য বা আর্থিক পরিচয়পত্র পোস্ট করবেন না।",
    termsS6P3: "সরকারি চক্রসূত্র বা নিশ্চিত রিটার্ন নিয়ে মিথ্যা দাবি পোস্ট করবেন না।",
    termsS6P4: "অন্য অ্যাকাউন্টে প্রবেশের চেষ্টা করবেন না বা সেবা ব্যাহত করবেন না।",
    termsS6Outro:
      "আপনি পোস্ট করা সামগ্রির মালিকানা ধরে রাখেন এবং প্রোটোটাইপের অন্য সাইন-ইন করা ব্যবহারকারীদের কাছে তা দেখানোর অনুমতি দেন। যে সামগ্রী এই নিয়ম ভাঙে তা সরানো হতে পারে।",
    termsS7H: "7. দায়বদ্ধতার সীমা",
    termsS7:
      "প্রোটোটাইপটি যেমন আছে তেমনই, কোনো ধরনের ওয়ারেন্টি ছাড়া দেওয়া হয়েছে। আইন অনুমোদিত সীমা পর্যন্ত সাহিতির ব্যবহার থেকে উদ্ভূত কোনো ব্যবসায়িক ক্ষতি, লাভের ক্ষতি বা পরোক্ষ ক্ষতির জন্য প্রকল্প দল দায়বদ্ধ নয়।",
    termsS8H: "8. প্রযোজ্য আইন ও বিরোধ",
    termsS8:
      "এই শর্তাবলি ভারতের আইনে দ্বারা নিয়ন্ত্রিত। কোনো বিরোধ সালিস ও সন্ধি আইন 1996-এর অধীনে একক সালিসকারীর কাছে রেফার করা হবে। সালিসের আসন ও স্থান নতুন দিল্লি এবং ভাষা ইংরেজি হবে। অন্য সব বিষয়ে নতুন দিল্লির আদালতগুলোর একচেটিয়া এখতিয়াদার থাকবে।",

