    authDisclaimer:
      "இந்த மாதிரி கைபேசி எண் மற்றும் கடவுச்சொல் மூலம் உள்நுழைகிறது. உண்மையான நிதிச் சேவையில் சரிபார்க்கப்பட்ட கைபேசி அங்கீகாரம் இருக்க வேண்டும். 30 நிமிட செயலின்மைக்குப் பிறகு அமர்வு முடிவடையும்.",
