    getStarted: "தொடங்கு",
    footerMission:
      "கிராமத்து நுண் தொழில்முனைவோருக்கு உள்ளூர் சூழலுடன் வணிக நிதி வழிகாட்டல். ஸ்மார்ட் இந்தியா ஹேக்கத்தான் 2026, MoSJE சிக்கல் அறிக்கை 26091-க்கான மாதிரி.",
    footerCredit: "டீம் சாஹிதி. ஸ்மார்ட் இந்தியா ஹேக்கத்தான் மாதிரி.",
    landingKicker: "ஸ்மார்ட் இந்தியா ஹேக்கத்தான் 2026",
    landingHeroBody:
      "பணம் முதலீடு செய்வதற்கு முன் கடன் திட்டமிடுங்கள், ஆவணங்களைத் திரட்டுங்கள், உங்கள் பகுதிச் சந்தையைப் புரிந்துகொள்ளுங்கள்.",
    landingAboutProject: "திட்டப் பற்றி",
    landingHowHelps: "சாஹிதி எப்படி உதவுகிறது",
    landingHowTitle: "முதல் சந்தை சோதனையிலிருந்து நம்பிக்கையான அடுத்த நகர்வு வரை.",
    landingStep1Body:
      "உங்கள் மார்ஜின் தொகையைத் திட்டச் செலவு, கடன் தொகை, புரியும் திருப்பப் பட்டியலாக மாற்றுங்கள்.",
    landingStep1Alt: "மகாராஷ்டிராவின் அயல் கடையில் தின்பண்ட அலமாரிகள்",
    landingStep2Body:
      "வங்கிக் கிளை வரிசையில் நிற்கும் முன் வங்கி எந்த ஆவணங்களைக் கேட்கும் என்று தெரிந்துகொள்ளுங்கள்.",
    landingStep2Alt: "மேசையில் ஆவணங்களை நிரப்பும் கைகள்",
    landingStep3Body:
      "வரைபடத்தில் லோஹேகானின் உண்மைக் கடைகள், மற்றும் வணிகம் எங்கு நடக்கிறது என்பதைக் காட்டும் சாஹிதி பாதுகாப்பு மண்டலங்கள்.",
    landingStep3Alt: "டெல்லி சந்தைக் கடையில் குவிக்கப்பட்ட புதிய காய்கறிகளும் பழங்களும்",
    landingEverydayKicker: "அன்றாட தொழில்முனைவோருக்காக வடிவமைக்கப்பட்டது",
    landingEverydayBody:
      "கடன் எண்கள், ஆவணங்கள், லோஹேகான் வரைபடம் ஆகியவற்றை உண்மை வாழ்க்கைக்கு அருகில் வையுங்கள் — சிற்றேட்டில் புதைக்காதீர்கள்.",
    landingOpenSahiti: "சாஹிதியைத் திற",
    landingDisclaimer:
      "ஸ்மார்ட் இந்தியா ஹேக்கத்தான் 2026, MoSJE சிக்கல் அறிக்கை 26091-க்கான மாதிரி. செயலியில் காட்டப்படும் சந்தை, வரைபட எண்கள் மாதிரி ஆய்வே ஒழிய அதிகாரப்பூர்வ தரவு அல்ல.",
    marketDhanoriDemand:
      "இருசக்கர வாகனங்களின் அதிகரித்த போக்குவரத்து பழுது-பராமரிப்பு தேவையை உயர்த்துகிறது.",
    marketDhanoriRoi:
      "சீரான கருவி முதலீடும் தொடர்ந்து வரும் உள்ளூர் வாடிக்கையாளர்களும் முன்கூட்டிய இடைநிலை இலாபத்தைத் தரலாம்.",
    marketAdypuDemand:
      "மலிவான உணவு மற்றும் மாலை தின்பண்டங்களுக்கு தொடர் மாணவர் தேவை, பருவத்திற்கு ஏற்ப மாறும்.",
    marketAdypuRoi:
      "சிறிய அளவு கடைகள் நிலையான விற்பனையை இலக்காகக் கொள்ளலாம், வாடகையும் உணவு வீணும் கட்டுப்படுத்தப்பட்டால்.",
    marketAirportDemand:
      "தினசரி வீட்டுத் தேவை பால் மற்றும் கூடுதல் பால் பொருட்களுக்கு வலு சேர்க்கிறது.",
    marketAirportRoi: "குளிர்-சங்கிலி கட்டுப்பாடும் கெட்டுப்போகாமையுமே இலாபத்தின் மையம்.",
    marketCharholiDemand:
      "விதைப்பு சுழற்சி மற்றும் மழை எதிர்பார்ப்பைப் பொறுத்து உள்ளீட்டுத் தேவை மாறும்.",
    marketCharholiRoi: "பருவ உச்சங்களில் செயல் மூலதனத் திட்டமிடல் செயலற்ற சரக்கைக் குறைக்கும்.",
    marketPorwalDemand:
      "மாணவர்களும் பணிபுரியும் குடியிருப்பாளர்களும் ஆக்கிரமிப்பை நிலைநாட்டுகிறார்கள்; நிறுவனத் தேவை மையப்படுத்தப்பட்டது.",
    marketPorwalRoi:
      "சொத்து விலை உயர்வு, ஆனால் நிலையான ஆக்கிரமிப்பு கணிக்கக்கூடிய ரொக்க ஓட்டத்தைத் தரலாம்.",
    marketSantNagarDemand:
      "அடர்ந்த குடியிருப்புத் தேவை நிலையானது, ஆனால் வசதி சில்லறை போட்டி தெரிகிறது.",
    marketSantNagarRoi: "இலாபம் வாங்கும் ஒழுக்கம் மற்றும் சரக்கு சுழற்சியைச் சார்ந்தது.",
    marketWagholiDemand:
      "திருமண மற்றும் பண்டிகைத் தேவை உச்சத்தை உருவாக்கும்; தினசரி தேவை மிதமானது.",
    marketWagholiRoi:
      "சரக்குத் தேர்வே முதன்மை ROI இயக்கி; மெதுவான வடிவமைப்புகளை அதிகம் சேமிக்க வேண்டாம்.",
    marketLohegaonDemand:
      "தேவை சந்தர்ப்பம்-சார்ந்தது, விலை உணர்திறன் கொண்டது. நம்பிக்கையும் ஹால்மார்க்கும் மறுவாங்கை பாதிக்கும்.",
    marketLohegaonRoi:
      "அதிக அமைப்பு செலவும் மெதுவான சரக்கு சுழற்சியும் நீண்ட திரும்ப காலத்தைக் குறிக்கும்.",
    aiPageDescription:
      "கடன், திட்டங்கள், ஆவணங்கள் அல்லது சந்தை பற்றிக் கேளுங்கள் — உங்கள் மொழியில்.",
