    landingHowHelps: "సాహితి ఎలా సహాయం చేస్తుంది",
    landingHowTitle: "మొదటి మార్కెట్ తనిఖీ నుండి ఆత్మవిశ్వాసంతో కూడిన తదుపరి అడుగు వరకు.",
    landingStep1Body:
      "మీ మార్జిన్ డబ్బును ప్రాజెక్ట్ ఖర్చు, రుణ మొత్తం, అర్థమయ్యే చెల్లింపు పట్టికగా మార్చండి.",
    landingStep1Alt: "మహారాష్ట్రలోని పరిసర కిరాణా దుకాణంలో స్నాక్స్ అరలు",
    landingStep2Body: "బ్యాంకు శాఖ వరుసలో నిలబడే ముందు బ్యాంకు ఏ పత్రాలు అడుగుతుందో తెలుసుకోండి.",
    landingStep2Alt: "టేబుల్‌పై పత్రాలు నింపుతున్న చేతులు",
    landingStep3Body:
      "మ్యాప్‌పై లోహేగావ్ నిజమైన దుకాణాలు, మరియు వ్యాపారం ఎక్కడ నడుస్తుందో చూపే సాహితి సేఫ్ జోన్లు.",
    landingStep3Alt: "ఢిల్లీ మార్కెట్ గాడిదపై కుడిచిన తాజా కూరగాయలు, పండ్లు",
    landingEverydayKicker: "రోజువారీ వ్యవస్థాపకుల కోసం రూపొందించబడింది",
    landingEverydayBody:
      "రుణ సంఖ్యలు, పత్రాలు, లోహేగావ్ మ్యాప్‌ను నిజ జీవితానికి దగ్గరగా ఉంచండి — బ్రోచర్‌లో పూడ్చకండి.",
    landingOpenSahiti: "సాహితిని తెరవండి",
    landingDisclaimer:
      "స్మార్ట్ ఇండియా హ్యాకథాన్ 2026, MoSJE సమస్యా ప్రకటన 26091 కోసం ప్రోటోటైప్. యాప్‌లో చూపిన మార్కెట్, మ్యాప్ సంఖ్యలు నమూనా పరిశోధన మాత్రమే, అధికారిక డేటా కాదు.",
    marketDhanoriDemand: "ద్విచక్ర వాహనాల పెరుగుదల రిపేర్లు-నిర్వహణ డిమాండ్ పెంచుతుంది.",
    marketDhanoriRoi:
      "సమతుల్య పనిముట్ల పెట్టుబడి, తిరిగి వచ్చే స్థానిక కస్టమర్లు ముందుగానే లాభనిష్పత్తినిస్తారు.",
    marketAdypuDemand:
      "సరసమైన భోజనం, సాయంత్రం స్నాక్స్‌కు నిరంతర విద్యార్థి డిమాండ్, సెమిస్టర్‌ను బట్టి మారుతుంది.",
    marketAdypuRoi: "చిన్న దుకాణాలు స్థిర అమ్మకాలు చేరుకోగలవు, అద్దె-ఆహార నష్టం నియంత్రితమైతే.",
    marketAirportDemand: "రోజువారీ గృహ డిమాండ్ పాలు, అదనపు డెయిరీ ఉత్పత్తులకు బలం చేస్తుంది.",
    marketAirportRoi: "కోల్డ్-చెయిన్ నియంత్రణ, పాడైపోకుండా ఉండటమే మార్జిన్‌కు మూలం.",
    marketCharholiDemand: "విత్తు చక్రాలు, వర్ష ఆశలను బట్టి ఇన్‌పుట్ డిమాండ్ మారుతుంది.",
    marketCharholiRoi: "సీజన్ ఉత్తుంగాల్లో పని మూలధన ప్రణాళిక నిరుపయోగ సరుకు తగ్గిస్తుంది.",
    marketPorwalDemand:
      "విద్యార్థులు, ఉద్యోగ నివాసులు ఆక్యుపెన్సీని నిలబెట్టుకుంటారు; సంస్థాగత డిమాండ్ కేంద్రీకృతం.",
    marketPorwalRoi:
      "ఆస్తి ఖర్చు ఎక్కువ, కానీ స్థిర ఆక్యుపెన్సీ ఊహించదగిన నగదు ప్రవాహాన్నిస్తుంది.",
    marketSantNagarDemand:
      "సాంద్ర నివాస డిమాండ్ స్థిరం, కానీ సువిధా చిల్లర వ్యాపార పోటీ కనిపిస్తుంది.",
    marketSantNagarRoi: "మార్జిన్ కొనుగోలు శిస్తు, సరుకు తిరిగే వేగంపై ఆధారపడుతుంది.",
    marketWagholiDemand:
      "పెళ్లి, పండుగల సీజన్ డిమాండ్ ఉత్తుంగాలు సృష్టిస్తుంది; రోజూ డిమాండ్ సాధారణం.",
    marketWagholiRoi: "సరుకు ఎంపికే ముఖ్య ROI చాలక; నెమ్మదిగా అమ్ముడయ్యే డిజైన్లను ఎక్కువ దాచకండి.",
    marketLohegaonDemand:
      "డిమాండ్ సందర్భాలపై ఆధారపడి ఉంటుంది, ధరలకు సున్నితం. నమ్మకం, హాల్‌మార్క్ మళ్లీ కొనడంపై ప్రభావం చూపుతాయి.",
    marketLohegaonRoi: "ఎక్కువ సెటప్ ఖర్చు, నెమ్మదిగా సరుకు తిరగడం అంటే పొడవాటి వసూళ్ల కాలం.",
    aiPageDescription: "రుణాలు, పథకాలు, పత్రాలు లేదా మార్కెట్ గురించి అడగండి — మీ భాషలో.",
    "cat.Hardware": "హార్డ్‌వేర్",
