type I18nValue = {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  /** Translate a key, filling {placeholders} with values. */
  t: (key: string, vars?: Record<string, string | number>) => string;
  /** Whether the current language defines the key (for optional catalog values). */
  has: (key: string) => boolean;
};

const I18nContext = createContext<I18nValue | null>(null);

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>("en");

  useEffect(() => {
    const saved = window.localStorage.getItem("sahiti-locale") as Locale | null;
    if (saved && labels[saved]) setLocaleState(saved);
  }, []);

  const value = useMemo<I18nValue>(
    () => ({
      locale,
      setLocale: (next: Locale) => {
        setLocaleState(next);
        window.localStorage.setItem("sahiti-locale", next);
      },
      t: (key: string, vars?: Record<string, string | number>) => {
        const template = labels[locale][key] ?? en[key] ?? key;
        if (!vars) return template;
        return template.replace(/\{(\w+)\}/g, (match, name: string) =>
          name in vars ? String(vars[name]) : match,
        );
      },
      has: (key: string) => labels[locale][key] !== undefined,
    }),
    [locale],
  );

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useLanguage(): I18nValue {
  const value = useContext(I18nContext);
  if (!value) throw new Error("useLanguage must be used within LanguageProvider");
  return value;
}

